+//! Identity and recorded evidence for a selected search result.
+
+use chrono::{DateTime, NaiveDate, Utc};
+use thiserror::Error;
+
+/// A member's source ID or a funder's exact stored name.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct EntityReference(Subject);
+
+#[derive(Clone, Debug, PartialEq, Eq)]
+enum Subject {
+    Member(i32),
+    Funder(String),
+}
+
+impl EntityReference {
+    /// Validates a Parliament member ID.
+    pub fn member(id: i32) -> Result<Self, InvalidDetailsRequest> {
+        if id <= 0 {
+            return Err(InvalidDetailsRequest::MemberId);
+        }
+        Ok(Self(Subject::Member(id)))
+    }
+
+    /// Preserves an exact funder name, including its case and whitespace.
+    pub fn funder(name: String) -> Result<Self, InvalidDetailsRequest> {
+        if name.trim().is_empty() || name.contains('\0') {
+            return Err(InvalidDetailsRequest::FunderReference);
+        }
+        Ok(Self(Subject::Funder(name)))
+    }
+
+    /// The selected Parliament member ID, when this is a member reference.
+    pub fn member_id(&self) -> Option<i32> {
+        match self.0 {
+            Subject::Member(id) => Some(id),
+            Subject::Funder(_) => None,
+        }
+    }
+
+    /// The exact selected name, when this is a funder reference.
+    pub fn funder_name(&self) -> Option<&str> {
+        match &self.0 {
+            Subject::Member(_) => None,
+            Subject::Funder(name) => Some(name),
+        }
+    }
+}
+
+/// A bounded page of declarations, ordered by registration date then source ID.
+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+pub struct HistoryPage {
+    limit: u16,
+    offset: u32,
+}
+
+impl HistoryPage {
+    /// Accepts 1–100 declarations and an offset up to the signed 32-bit maximum.
+    pub fn new(limit: u16, offset: u32) -> Result<Self, InvalidDetailsRequest> {
+        if !(1..=100).contains(&limit) || offset > i32::MAX as u32 {
+            return Err(InvalidDetailsRequest::Page);
+        }
+        Ok(Self { limit, offset })
+    }
+
+    /// Maximum declarations in the response.
+    pub fn limit(self) -> u16 {
+        self.limit
+    }
+
+    /// Declarations to skip in the deterministic ordering.
+    pub fn offset(self) -> u32 {
+        self.offset
+    }
+}
+
+/// Invalid entity selection or history bounds.
+#[derive(Debug, Error)]
+pub enum InvalidDetailsRequest {
+    /// Parliament IDs must be positive signed 32-bit integers.
+    #[error("member ID must be a positive 32-bit integer")]
+    MemberId,
+    /// The funder reference cannot represent an empty name or contain NUL.
+    #[error("invalid funder reference")]
+    FunderReference,
+    /// History bounds are invalid.
+    #[error("limit must be between 1 and 100; offset must be between 0 and 2147483647")]
+    Page,
+}
+
+/// Latest recorded identity of an MP; party attribution is not historical.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct MemberIdentity {
+    /// Parliament's stable member ID.
+    pub member_id: i32,
+    /// Name as recorded by the source.
+    pub name: String,
+    /// Latest recorded party ID.
+    pub party_id: i32,
+    /// Latest recorded party name.
+    pub party_name: String,
+    /// Latest House: 1 is Commons, 2 is Lords.
+    pub latest_house: i16,
+    /// Latest membership location; only a Commons location is a constituency.
+    pub latest_membership_from: String,
+    /// Whether the source currently places the member in the Commons.
+    pub is_current_commons: bool,
+}
+
+/// An exact recorded funder name, without alias or company resolution.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct FunderIdentity {
+    /// Exact stored name.
+    pub name: String,
+    /// Source donor status, when known.
+    pub funder_kind: Option<String>,
+    /// Source company identifier, preserving leading zeros.
+    pub company_number: Option<String>,
+}
+
+/// Identity of the selected entity.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub enum EntityIdentity {
+    /// A member of Parliament.
+    Member(MemberIdentity),
+    /// A named funder.
+    Funder(FunderIdentity),
+}
+
+/// One stored funding item, including unknown values.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct RecordedFunding {
+    /// Attributed funder, if the source identifies one.
+    pub funder: Option<FunderIdentity>,
+    /// Exact decimal text; absent amounts remain unknown.
+    pub amount: Option<String>,
+    /// Recorded currency, if present.
+    pub currency: Option<String>,
+    /// Monetary or in-kind classification, if present.
+    pub payment_type: Option<String>,
+}
+
+/// A declaration and all its funding items, including other funders as context.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct RecordedDeclaration {
+    /// Parliament's stable declaration ID.
+    pub source_declaration_id: i32,
+    /// Owning MP and their latest recorded identity.
+    pub member: MemberIdentity,
+    /// Source category ID.
+    pub category_id: i32,
+    /// Source category name.
+    pub category_name: String,
+    /// Registration date, when supplied by the source.
+    pub registration_date: Option<NaiveDate>,
+    /// When this stored representation was fetched.
+    pub fetched_at: DateTime<Utc>,
+    /// Funding items in stable storage order; repeated items retain multiplicity.
+    pub funding_entries: Vec<RecordedFunding>,
+}
+
+/// One internally consistent view of an entity and its recorded declarations.
+#[derive(Clone, Debug, PartialEq, Eq)]
+pub struct EntityDetails {
+    /// Selected entity, including entities with no declarations.
+    pub entity: EntityIdentity,
+    /// Dated declarations newest first, source ID descending for ties; undated last.
+    pub declarations: Vec<RecordedDeclaration>,
+    /// Whether another page exists in this snapshot.
+    pub has_more: bool,
+}
+
