+        assert!(HistoryPage::new(0, 0).is_err());
+        assert!(HistoryPage::new(101, 0).is_err());
+        assert!(HistoryPage::new(50, u32::MAX).is_err());
+        assert!(HistoryPage::new(100, 0).is_ok());
+    }
+}
