+//! Retrieve a selected entity and distinguish missing data from read failures.
+
+use thiserror::Error;
+
+use crate::domain::{
+    models::entity_details::{EntityDetails, EntityReference, HistoryPage},
+    repositories::entity_details_repository::{EntityDetailsRepo, EntityDetailsRepoError},
+};
+
+/// Application interface for entity detail pages.
+pub trait EntityDetailsService: Clone + Send + Sync + 'static {
+    /// Retrieves the selected entity's identity and requested declaration page.
+    fn get_entity_details(
+        &self,
+        reference: &EntityReference,
+        page: HistoryPage,
+    ) -> impl Future<Output = Result<EntityDetails, EntityDetailsError>> + Send;
+}
+
+/// Detail-page application service.
+#[derive(Clone)]
+pub struct Service<R> {
+    repo: R,
+}
+
+impl<R> Service<R> {
+    /// Uses the supplied read repository.
+    pub fn new(repo: R) -> Self {
+        Self { repo }
+    }
+}
+
+impl<R: EntityDetailsRepo> EntityDetailsService for Service<R> {
+    async fn get_entity_details(
+        &self,
+        reference: &EntityReference,
+        page: HistoryPage,
+    ) -> Result<EntityDetails, EntityDetailsError> {
+        self.repo
+            .get_entity_details(reference, page)
+            .await?
+            .ok_or(EntityDetailsError::NotFound)
+    }
+}
+
+/// Expected outcomes when retrieving a detail page.
+#[derive(Debug, Error)]
+pub enum EntityDetailsError {
+    /// The selected identity is not stored.
+    #[error("entity not found")]
+    NotFound,
+    /// The read failed; this is not an empty history or unknown entity.
+    #[error(transparent)]
+    Unavailable(#[from] EntityDetailsRepoError),
+}
